css:
.luxury-btn {
  position: relative;
  min-width: 200px;
  padding: 15px 30px;
  border: none;
  background: linear-gradient(135deg, #2a1a4a 0%, #4a2b8a 100%);
  color: #e0e0e0;
  cursor: pointer;
  overflow: hidden;
  transform: translateY(0);
  box-shadow: 0 4px 15px rgba(74, 43, 138, 0.2);
  transition:
    transform 0.2s,
    box-shadow 0.2s,
    background 0.3s;
}

.luxury-btn__text {
  position: relative;
  z-index: 2;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.luxury-btn__border {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
}

.luxury-btn__border-path {
  stroke: #d4af37;
  stroke-width: 2;
  transition:
    stroke-dasharray 0.3s,
    stroke-dashoffset 0.3s;
  stroke-dasharray: 400;
  stroke-dashoffset: 400;
}

.luxury-btn:hover .luxury-btn__border-path {
  stroke-dashoffset: 0;
}

.luxury-btn__ornament-left,
.luxury-btn__ornament-right {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  color: #d4af37;
  transition: transform 0.3s;
}

.luxury-btn__ornament-left {
  left: 15px;
}

.luxury-btn__ornament-right {
  right: 15px;
}

.luxury-btn:hover .luxury-btn__ornament-left {
  transform: translateY(-50%) rotate(-180deg);
}

.luxury-btn:hover .luxury-btn__ornament-right {
  transform: translateY(-50%) rotate(180deg);
}

.luxury-btn__shine {
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 3;
  animation: shine-effect 3s infinite;
}

@keyframes shine-effect {
  0% {
    transform: translateX(0%);
    opacity: 0;
  }
  10% {
    opacity: 0.5;
  }
  50% {
    transform: translateX(200%);
    opacity: 0.5;
  }
  100% {
    transform: translateX(200%);
    opacity: 0;
  }
}

.luxury-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(74, 43, 138, 0.3);
  background: linear-gradient(135deg, #321f57 0%, #5633a6 100%);
}

.luxury-btn:active {
  transform: translateY(1px);
  box-shadow: 0 2px 10px rgba(74, 43, 138, 0.1);
  background: linear-gradient(135deg, #231640 0%, #3d2475 100%);
}
